mapper.select:
SELECT ps.id AS sessionId, ps.person_id AS personId, ps.track_key AS trackKey, (ps.enter_body_embedding <=> #{embedding}::vector) AS distance, (1 - (ps.enter_body_embedding <=> #{embedding}::vector)) AS score FROM presence_sessions ps WHERE ps.camera_id = #{cameraId} AND ps.status = 'open' AND ps.enter_body_embedding IS NOT NULL AND (ps.enter_body_embedding <=> #{embedding}::vector) <= #{maxDistance}
AND ps.arrival_at <= #{eventTime}
ORDER BY ps.enter_body_embedding <=> #{embedding}::vector LIMIT 1
